import sceneData from "../../../../public/meloneditor/src/helper/tilemap-scene.js";

/**
 * TMX layer menerima redraw rectangle dalam coordinate space tempat layer
 * digambar.
 *
 * TilemapScene adalah Container yang punya posisi sendiri, sedangkan melonJS
 * mengirim viewport rectangle ke child dalam world coordinates.
 *
 * Jadi viewport harus dikonversi ke TilemapScene-local coordinates terlebih
 * dahulu sebelum TMX melakukan tile culling.
 */
function localTilemapRect(scene, rect) {
    if (!rect?.pos) return rect;

    const absolute =
        typeof scene.getAbsolutePosition === "function"
            ? scene.getAbsolutePosition()
            : scene.pos;

    const originX = Number(absolute?.x) || 0;
    const originY = Number(absolute?.y) || 0;

    const viewX = scene.floating === true ? 0 : Number(rect.pos.x) || 0;

    const viewY = scene.floating === true ? 0 : Number(rect.pos.y) || 0;

    const x = viewX - originX;
    const y = viewY - originY;

    const width = Number(rect.width) || 0;
    const height = Number(rect.height) || 0;

    return {
        pos: {
            x,
            y,
        },

        width,
        height,

        left: x,
        top: y,
        right: x + width,
        bottom: y + height,
    };
}

/**
 * Reusable tilemap container.
 *
 * Tidak mengubah active level atau camera bounds.
 */
export function createTilemapSceneClass(engine) {
    return class TilemapScene extends engine.Container {
        constructor(x, y, source, settings = {}) {
            const data = sceneData.normalize(source);
            const bounds = sceneData.size(data);

            super(x, y, bounds.width, bounds.height);

            this.anchorPoint.set(0, 0);

            this.name = settings.name || "tilemapScene";

            this.tilemapData = data;

            this.autoSort = false;
            this.autoDepth = false;

            this.alwaysUpdate = settings.alwaysUpdate ?? true;

            this.floating = settings.floating ?? false;

            this._tilesetAssets = new Map();

            /*
             * Build internal TMX map
             */
            const mapData = sceneData.buildMap(data, (id, name) => {
                const asset = settings.resolveTileset
                    ? settings.resolveTileset(id, name)
                    : engine.loader.getTMX(name);

                this._tilesetAssets.set(id, asset);

                return asset;
            });

            this.tilemap = new engine.TMXTileMap(this.name, mapData);

            try {
                /*
                 * Jangan pakai tilemap.addTo().
                 *
                 * addTo() pada beberapa versi melonJS dapat mengubah
                 * bounds / position container.
                 *
                 * TilemapScene harus mempertahankan posisi dan ukuran
                 * prefab-nya sendiri.
                 */
                this.tilemap.getLayers().forEach((layer, index) => {
                    /*
                     * FIX FLICKERING TILE
                     *
                     * Nested TilemapScene jangan menggunakan GPU
                     * tile shader secara default.
                     *
                     * Shader tile path menggunakan texture tambahan
                     * untuk tile-index. Texture unit tersebut dapat
                     * terganti ketika renderer melakukan batching
                     * texture lain di frame yang sama.
                     *
                     * Gejalanya:
                     * - beberapa tile hilang 1 frame
                     * - tile muncul lagi frame berikutnya
                     * - tile random berkedip ketika kamera bergerak
                     *
                     * perTile lebih stabil untuk nested tilemap.
                     *
                     * Kalau nanti shader renderer sudah diperbaiki,
                     * masih bisa dioverride:
                     *
                     * {
                     *     tileRenderMode: "shader"
                     * }
                     */
                    layer.renderMode = settings.tileRenderMode ?? "perTile";

                    /*
                     * FIX TILE CULLING
                     *
                     * Original layer.draw menerima viewport world-space.
                     *
                     * Tetapi layer ini digambar di dalam TilemapScene
                     * Container sehingga drawTileLayer mengharapkan
                     * rectangle dalam TilemapScene-local space.
                     */
                    const originalDraw = layer.draw;

                    layer.draw = (renderer, rect) => {
                        const localRect = localTilemapRect(this, rect);

                        return originalDraw.call(layer, renderer, localRect);
                    };

                    /*
                     * Add layer langsung sebagai child TilemapScene.
                     */
                    this.addChild(layer, index);
                });

                /*
                 * Add object layer / collision object / dll.
                 */
                this.tilemap.getObjects(true).forEach((object) => {
                    this.addChild(object);
                });
            } catch (error) {
                this.destroy();

                throw error;
            }
        }

        getTile(layerIndex, column, row) {
            if (![layerIndex, column, row].every(Number.isInteger)) {
                return 0;
            }

            return (
                this.tilemapData.layers[layerIndex]?.tiles[row]?.[column] ?? 0
            );
        }

        getTileProperties(layerIndex, column, row) {
            const layer = this.tilemapData.layers[layerIndex];

            const tile = this.getTile(layerIndex, column, row);

            if (!tile) {
                return {};
            }

            return {
                ...(this._tilesetAssets.get(layer.tileset)?.tileproperties?.[
                    tile - 1
                ] || {}),
            };
        }

        getTileLayer(layerIndex) {
            return this.tilemap?.getLayers()[layerIndex] ?? null;
        }

        destroy() {
            super.destroy();

            this.tilemap?.destroy();

            this.tilemap = null;

            this._tilesetAssets?.clear();
        }
    };
}
