import { normalizeParticleEffect2D, validateParticleEffect2D } from "./particle-effect-2d.js";

export const LEGACY_PARTICLE_MIGRATION_VERSION = 1;
export const LEGACY_PARTICLE_DEPRECATION_POLICY = Object.freeze({
    status: "supported",
    defaultPath: "legacy",
    migration: "explicit-opt-in",
    targets: Object.freeze(["17.4.0", "20.0.0"]),
    removal: "no-removal-in-release-1"
});

export class ParticleMigrationError extends Error {
    constructor(code, message, details = {}) { super(message); this.name = "ParticleMigrationError"; this.code = code; this.details = details; }
}

const clone = value => JSON.parse(JSON.stringify(value));
const finite = (value, fallback) => Number.isFinite(value) ? value : fallback;
const idPart = value => String(value ?? "legacy").replace(/[^A-Za-z0-9._:-]+/g, "-").replace(/^[^A-Za-z]+/, "") || "legacy";

function stableJson(value) {
    if (Array.isArray(value)) return `[${value.map(stableJson).join(",")}]`;
    if (value && typeof value === "object") return `{${Object.keys(value).sort().map(key => `${JSON.stringify(key)}:${stableJson(value[key])}`).join(",")}}`;
    return JSON.stringify(value);
}

function checksum(value) {
    const text = stableJson(value); let hash = 2166136261;
    for (let index = 0; index < text.length; index += 1) { hash ^= text.charCodeAt(index); hash = Math.imul(hash, 16777619); }
    return `fnv1a32:${(hash >>> 0).toString(16).padStart(8, "0")}`;
}

export function detectParticleAssetKind(asset) {
    if (!asset || typeof asset !== "object" || Array.isArray(asset)) return "unknown";
    if (asset.assetType === "particle-effect-2d") return "advanced";
    if (String(asset.extend ?? "").includes("ParticleEmitter") || ["image_selected", "emitMethod", "totalParticles", "lifeTime"].some(key => key in asset)) return "legacy-flat";
    return "unknown";
}

function legacyV0ToV1(source, options) {
    const name = idPart(source.name ?? "legacy-particle"); const lifeMs = finite(source.lifeTime, finite(source.maxLife, finite(source.minLife, 1000))); const lifetime = Math.max(0.001, lifeMs / 1000);
    const startScale = finite(source.startScale, finite(source.maxStartScale, finite(source.minStartScale, 1))); const endScale = finite(source.endScale, finite(source.maxEndScale, finite(source.minEndScale, 0)));
    const speed = finite(source.speed, 0); const variation = Math.max(0, finite(source.speedVariation, 0)); const angle = finite(source.angle, 0); const radians = angle * Math.PI / 180;
    const total = Math.max(1, Math.floor(finite(source.totalParticles, 50))); const maxParticles = Math.max(total, Math.floor(finite(source.maxParticles, total)));
    const method = source.emitMethod ?? ""; const isBurst = method === "burst"; const isStream = method === "stream_duration" || method === "stream_infinity"; const finiteStream = method === "stream_duration";
    const textureId = source.image_selected ? `texture.${name}` : null; const gradientId = `gradient.${name}.legacy-alpha`; const scaleCurveId = `curve.${name}.legacy-scale`;
    const speedValue = variation > 0 ? { type: "scalar", mode: "randomBetweenConstants", min: (speed - variation) * 60, max: (speed + variation) * 60 } : speed * 60;
    const startRenderedScale = startScale * startScale; const endRatio = startScale === 0 ? 0 : endScale / startScale;
    const migrated = {
        assetType: "particle-effect-2d", schemaVersion: 1,
        effect: { id: `effect.${name}`, name: source.name ?? "Migrated Legacy Particle", enabled: true, duration: finiteStream ? Math.max(0.001, finite(source.duration, 5000) / 1000) : lifetime, looping: method === "stream_infinity", autoRandomSeed: false, randomSeed: options.seed ?? 1, simulationSpace: source.floating ? "world" : "local" },
        systems: [{ id: `system.${name}`, enabled: true, renderer: { enabled: true, type: "sprite", textureId, atlasRegionId: null, blendMode: source.blendMode && source.blendMode !== "normal" ? source.blendMode : (source.textureAdditive ? "additive" : "normal"), z: finite(source.z, 0), bounds: { mode: "auto", padding: 0 } }, emitters: [{ id: `emitter.${name}`, enabled: true, modules: {
            main: { enabled: true, maxParticles, duration: finiteStream ? Math.max(0.001, finite(source.duration, 5000) / 1000) : lifetime, looping: method === "stream_infinity", startLifetime: lifetime, startSpeed: speedValue, startSize: startRenderedScale, startRotation: { type: "angle", mode: "randomBetweenConstants", min: finite(source.minRotation, 0), max: finite(source.maxRotation, finite(source.minRotation, 0)) }, simulationSpace: source.floating ? "world" : "local", cullingMode: "simulate", overflowPolicy: "reject" },
            emission: { enabled: isBurst || isStream, rateOverTime: isStream ? total / lifetime : 0, bursts: isBurst ? [{ id: `burst.${name}.legacy`, time: 0, count: total, cycles: 1, probability: 1 }] : [], maxSpawnPerFrame: Math.max(total, 1), catchUpPolicy: "carry" },
            shape: { enabled: true, type: "rectangle", width: Math.max(0, finite(source.width, 32)), height: Math.max(0, finite(source.height, 32)), emitFrom: "area", direction: "fixed", fixedDirection: { x: Math.cos(radians), y: Math.sin(radians) }, legacyAngleVariation: finite(source.angleVariation, 0) },
            velocityOverLifetime: { enabled: false }, forceOverLifetime: { enabled: finite(source.wind, 0) !== 0 || finite(source.gravity, 0) !== 0, x: finite(source.wind, 0) * 3600, y: finite(source.gravity, 0) * 3600, space: "world", mass: 1 },
            colorOverLifetime: { enabled: true, gradientId }, sizeOverLifetime: { enabled: true, curveId: scaleCurveId }, rotationOverLifetime: { enabled: source.followTrajectory === true, orientation: source.followTrajectory ? "velocity" : "free", value: 0 }
        } }] }],
        libraries: { curves: [{ id: scaleCurveId, interpolation: "linear", multiplier: 1, keys: [{ time: 0, value: 1 }, { time: 1, value: endRatio }] }], gradients: [{ id: gradientId, colorSpace: "srgb", colorKeys: [{ time: 0, color: [1, 1, 1] }, { time: 1, color: [1, 1, 1] }], alphaKeys: [{ time: 0, alpha: 1 }, { time: 1, alpha: 0 }] }] },
        dependencies: { textures: textureId ? [{ id: textureId, kind: "texture", assetId: source.image_selected, required: true }] : [], atlasRegions: [], objects: [], shaders: [], collisionLayers: [], subEffects: [] },
        overrides: { platforms: [], qualities: [] },
        metadata: { tags: ["migrated", "legacy-particle"], author: "", description: "Opt-in migration from legacy ParticleEmitter.", migration: { version: 1, mode: options.compatibilityMode ?? "legacy-approximate", sourceChecksum: checksum(source) }, legacySource: clone(source) }
    };
    const normalized = normalizeParticleEffect2D(migrated); const validation = validateParticleEffect2D(normalized);
    if (!validation.valid) throw new ParticleMigrationError("APS_MIGRATION_INVALID_OUTPUT", "Legacy migration produced an invalid ParticleEffect2D.", { errors: validation.errors });
    return normalized;
}

export const LEGACY_PARTICLE_MIGRATIONS = Object.freeze([{ from: 0, to: 1, migrate: legacyV0ToV1 }]);

export function migrateLegacyParticleEffect(asset, options = {}) {
    const kind = detectParticleAssetKind(asset);
    if (kind === "advanced") return clone(asset);
    if (kind !== "legacy-flat") throw new ParticleMigrationError("APS_MIGRATION_UNKNOWN_SOURCE", "Asset is neither legacy ParticleEmitter data nor ParticleEffect2D.");
    return LEGACY_PARTICLE_MIGRATIONS[0].migrate(clone(asset), options);
}

export function previewLegacyParticleMigration(asset, options = {}) {
    const migrated = migrateLegacyParticleEffect(asset, options); const source = clone(asset);
    const changes = [
        { from: "lifeTime/minLife/maxLife", to: "main.startLifetime", value: migrated.systems[0].emitters[0].modules.main.startLifetime },
        { from: "speed/speedVariation/angle", to: "main.startSpeed + shape.fixedDirection", value: migrated.systems[0].emitters[0].modules.main.startSpeed },
        { from: "startScale/endScale aliases", to: "main.startSize + size curve", value: migrated.systems[0].emitters[0].modules.main.startSize },
        { from: "legacy alpha fade", to: "color gradient", value: migrated.libraries.gradients[0].id },
        { from: "emitMethod/totalParticles/lifeTime", to: "emission rate/burst", value: migrated.systems[0].emitters[0].modules.emission },
        { from: "image_selected/textureAdditive/blendMode", to: "dependency + renderer", value: migrated.systems[0].renderer }
    ];
    const warnings = [{ code: "APS_MIGRATION_APPROXIMATE_SCHEDULING", severity: "warning", message: "Legacy frequency/maxParticles scheduling and unseeded randomness are preserved in backup but only approximated by the advanced deterministic scheduler." }];
    if (finite(source.angleVariation, 0) !== 0) warnings.push({ code: "APS_MIGRATION_APPROXIMATE_ANGLE", severity: "warning", message: "Legacy symmetric launch-angle variation is retained as migration metadata and may differ visually." });
    return Object.freeze({ source, migrated, changes: Object.freeze(changes), warnings: Object.freeze(warnings), exact: false, requiresExplicitSave: true });
}

export function createLegacyParticleMigrationBackup(asset, migrated = migrateLegacyParticleEffect(asset)) {
    const original = clone(asset); const output = clone(migrated);
    return Object.freeze({ format: "particle-effect-2d-migration-backup", version: 1, original, migrated: output, originalChecksum: checksum(original), migratedChecksum: checksum(output) });
}

export function recoverLegacyParticleMigrationBackup(backup) {
    if (backup?.format !== "particle-effect-2d-migration-backup" || backup.version !== 1 || checksum(backup.original) !== backup.originalChecksum || checksum(backup.migrated) !== backup.migratedChecksum) throw new ParticleMigrationError("APS_MIGRATION_BACKUP_INVALID", "Migration backup is invalid or modified.");
    return clone(backup.original);
}
