import { createAnimationModule } from "./modules/animation.js";
import { createAudioModule } from "./modules/audio.js";
import { createBehaviorModule } from "./modules/behavior.js";
import { createCameraModule } from "./modules/camera.js";
import { createCapabilitiesModule } from "./modules/capabilities.js";
import { createCollisionModule } from "./modules/collision.js";
import { createEventsModule } from "./modules/events.js";
import { createGameModule } from "./modules/game.js";
import { createGroupModule } from "./modules/group.js";
import { createInputModule } from "./modules/input.js";
import { createMathModule } from "./modules/math.js";
import { createMovementModule } from "./modules/movement.js";
import { createObjectModule } from "./modules/object.js";
import { createParticlesModule } from "./modules/particles.js";
import { createSceneModule } from "./modules/scene.js";
import { createSpriteModule } from "./modules/sprite.js";
import { createStorageModule } from "./modules/storage.js";
import { createStateModule } from "./modules/state.js";
import { createTimeModule } from "./modules/time.js";
import { createTexturesModule } from "./modules/textures.js";
import { createAudioSourceModule } from "./modules/audioSource.js";
import { createBitmapTextModule } from "./modules/bitmapText.js";
import { createDraggableModule } from "./modules/draggable.js";
import { createLightModule } from "./modules/light.js";
import { createParticleEmitterModule } from "./modules/particleEmitter.js";
import { createRenderableModule } from "./modules/renderable.js";
import { createSliderModule } from "./modules/slider.js";
import { createSprite25Module } from "./modules/sprite25.js";
import { createTextModule } from "./modules/text.js";
import { createTrailModule } from "./modules/trail.js";
import { createTriggerModule } from "./modules/trigger.js";
import { createUiModule } from "./modules/ui.js";
import { createVideoModule } from "./modules/video.js";

export const MELON_RUNTIME_VERSION = "0.4.0";

export * from "./particle/particle-effect-2d.js";
export * from "./particle/particle-values.js";
export * from "./particle/deterministic-random.js";
export * from "./particle/particle-state.js";
export * from "./particle/particle-system-2d.js";
export * from "./particle/particle-main-emission.js";
export * from "./particle/particle-shapes.js";
export * from "./particle/particle-motion.js";
export * from "./particle/particle-visual-properties.js";
export * from "./particle/particle-noise-fields.js";
export * from "./particle/particle-texture-renderer.js";
export * from "./particle/particle-collision.js";
export * from "./particle/particle-subemitters-events.js";
export * from "./particle/particle-trails-lights-custom.js";
export * from "./particle/particle-runtime-modules.js";
export * from "./particle/particle-preview-profiler.js";
export * from "./particle/particle-performance.js";
export * from "./particle/particle-migration.js";
export * from "./particle/particle-presets.js";
export * from "./particle/particle-release.js";
export * from "./adapters/particle-system-2d-engine.js";

export function createMelonRuntime(adapter, initialOptions = {}) {
    if (!adapter || typeof adapter !== "object") {
        throw new TypeError("Melon Runtime membutuhkan adapter engine.");
    }

    const context = {
        adapter,
        gameData: initialOptions.gameData ?? null,
        options: { ...initialOptions },
        state: {
            actions: new Map(),
            behavior: new WeakMap(),
            groups: new Map(),
            objectData: new WeakMap(),
            values: new Map(),
            valueWatchers: new Map()
        }
    };

    const melon = {
        name: "Melon Runtime",
        version: MELON_RUNTIME_VERSION,
        engineAdapter: adapter.name ?? "unknown",

        configure(options = {}) {
            context.options = { ...context.options, ...options };
            if (Object.prototype.hasOwnProperty.call(options, "gameData")) {
                context.gameData = options.gameData;
            }
            adapter.configure?.(options);
            if (context.gameData && typeof context.gameData === "object") {
                context.gameData.melon = melon;
            }
            return melon;
        },

        get gameData() {
            return context.gameData;
        }
    };

    melon.math = createMathModule(context);
    melon.events = createEventsModule(context);
    melon.object = createObjectModule(context);
    melon.particles = createParticlesModule(context);
    melon.group = createGroupModule(context);
    melon.movement = createMovementModule(context);
    melon.behavior = createBehaviorModule(context);
    melon.input = createInputModule(context);
    melon.animation = createAnimationModule(context);
    melon.audio = createAudioModule(context);
    melon.scene = createSceneModule(context);
    melon.sprite = createSpriteModule(context);
    melon.renderable = createRenderableModule(context);
    melon.video = createVideoModule(context);
    melon.text = createTextModule(context);
    melon.bitmapText = createBitmapTextModule(context);
    melon.trigger = createTriggerModule(context);
    melon.draggable = createDraggableModule(context);
    melon.ui = createUiModule(context);
    melon.slider = createSliderModule(context);
    melon.trail = createTrailModule(context);
    melon.light = createLightModule(context);
    melon.particleEmitter = createParticleEmitterModule(context);
    melon.audioSource = createAudioSourceModule(context);
    melon.sprite25 = createSprite25Module(context);
    melon.camera = createCameraModule(context);
    melon.capabilities = createCapabilitiesModule(context);
    melon.time = createTimeModule(context);
    melon.textures = createTexturesModule(context);
    melon.storage = createStorageModule(context);
    melon.state = createStateModule(context);
    melon.collision = createCollisionModule(context);
    melon.game = createGameModule(context);

    return melon.configure(initialOptions);
}
