import { evaluateParticleValue } from "./particle-values.js";
import { compileScalar, deterministicUnit, addModuleEvaluator } from "./particle-module-utils.js";
import { unpackParticleColor } from "./particle-state.js";

export const PARTICLE_EVENT_ORDER = Object.freeze([
    "system-play", "system-restart", "burst", "particle-birth", "particle-continuous",
    "particle-collision", "particle-trigger", "custom", "particle-death", "system-loop", "system-complete"
]);

export class ParticleEventsError extends Error {
    constructor(code, message, details = {}) { super(message); this.name = "ParticleEventsError"; this.code = code; this.details = details; }
}

export class ParticleEventQueue {
    constructor(options = {}) {
        this.maximum = Math.max(1, Math.floor(options.maximum ?? 4096));
        this.events = [];
        this.subscribers = new Map();
        this.sequence = 0;
        this.dropped = 0;
        this.disposed = false;
        this.onSubscriberError = options.onSubscriberError ?? null;
    }
    enqueue(type, payload = {}, time = 0) {
        if (this.disposed) return false;
        if (this.events.length >= this.maximum) { this.dropped += 1; return false; }
        this.events.push({ type, time, sequence: this.sequence++, ...payload });
        return true;
    }
    subscribe(type, listener) {
        if (this.disposed || typeof listener !== "function") throw new ParticleEventsError("APS_EVENTS_INVALID_SUBSCRIBER", "A live queue and listener are required.");
        const bucket = this.subscribers.get(type) ?? [];
        if (!bucket.includes(listener)) bucket.push(listener);
        this.subscribers.set(type, bucket);
        return () => this.unsubscribe(type, listener);
    }
    unsubscribe(type, listener) {
        const bucket = this.subscribers.get(type); if (!bucket) return false;
        const index = bucket.indexOf(listener); if (index < 0) return false;
        bucket.splice(index, 1); if (bucket.length === 0) this.subscribers.delete(type); return true;
    }
    clear() { const removed = this.events.length; this.events.length = 0; return removed; }
    flush() {
        if (this.events.length === 0) return Object.freeze({ events: [], dropped: this.dropped });
        const events = this.events.splice(0).sort((a, b) => a.time - b.time || a.sequence - b.sequence);
        const byType = new Map();
        for (const event of events) (byType.get(event.type) ?? (byType.set(event.type, []), byType.get(event.type))).push(event);
        for (const [type, batch] of byType) {
            const listeners = [...(this.subscribers.get(type) ?? []), ...(this.subscribers.get("*") ?? [])];
            for (const listener of listeners) {
                try { listener(Object.freeze({ type, events: batch, dropped: this.dropped })); }
                catch (error) { this.onSubscriberError?.(error, type, listener); }
            }
        }
        const result = Object.freeze({ events, dropped: this.dropped }); this.dropped = 0; return result;
    }
    dispose() { this.clear(); this.subscribers.clear(); this.disposed = true; }
}

export function detectParticleEffectCycles(effectId, linksByEffect, maximumDepth = 8) {
    const errors = [];
    const visit = (id, path) => {
        if (path.length > maximumDepth) { errors.push({ code: "APS_SUBEMITTER_DEPTH_LIMIT", path: [...path, id] }); return; }
        const cycleIndex = path.indexOf(id);
        if (cycleIndex >= 0) { errors.push({ code: "APS_SUBEMITTER_CYCLE", path: [...path.slice(cycleIndex), id] }); return; }
        for (const next of linksByEffect.get(id) ?? []) visit(next, [...path, id]);
    };
    visit(effectId, []);
    return errors;
}

function compileLink(link, index, context) {
    const event = link.event ?? "birth";
    if (!["birth", "continuous", "death", "collision", "trigger", "custom"].includes(event)) throw new ParticleEventsError("APS_SUBEMITTER_INVALID_EVENT", `Unknown sub-emitter event '${event}'.`, { index });
    return {
        ...link,
        id: String(link.id ?? `link.${index}`), event,
        enabled: link.enabled !== false,
        probability: compileScalar(link.probability ?? 1, context, `$.subEmitters.links[${index}].probability`, "probability"),
        count: compileScalar(link.count ?? 1, context, `$.subEmitters.links[${index}].count`),
        delay: Math.max(0, link.delay ?? 0),
        maximumSpawn: Math.max(0, Math.floor(link.maximumSpawn ?? 256)),
        interval: Math.max(1e-6, link.interval ?? 0.1),
        inherit: { position: true, velocity: false, rotation: false, size: false, color: false, lifetimeRatio: false, seed: true, customData: false, ...(link.inherit ?? {}) },
        followParent: link.followParent === true,
        spawned: 0
    };
}

export class ParticleSubEmitterModule {
    constructor(system, source = {}, options = {}) {
        this.system = system;
        this.source = {
            enabled: source.enabled === true,
            maximumDepth: Math.max(1, Math.floor(source.maximumDepth ?? 4)),
            eventBudget: Math.max(1, Math.floor(source.eventBudget ?? 1024)),
            spawnBudget: Math.max(0, Math.floor(source.spawnBudget ?? 256))
        };
        this.context = options.context ?? {};
        this.links = (source.links ?? []).map((link, index) => compileLink(link, index, this.context));
        this.eventQueue = options.eventQueue ?? new ParticleEventQueue({ maximum: this.source.eventBudget, onSubscriberError: options.onSubscriberError });
        this.ownsQueue = !options.eventQueue;
        this.spawnEffect = options.spawnEffect ?? null;
        this.readCustomData = options.readCustomData ?? null;
        this.effectId = String(options.effectId ?? system.systemId);
        this.ancestry = [...(options.ancestry ?? [])];
        if (this.ancestry.includes(this.effectId) || this.ancestry.length >= this.source.maximumDepth) throw new ParticleEventsError(this.ancestry.includes(this.effectId) ? "APS_SUBEMITTER_CYCLE" : "APS_SUBEMITTER_DEPTH_LIMIT", "Sub-emitter recursion is not allowed.");
        for (const link of this.links) if ((link.subEffectId ?? link.systemId) === this.effectId) throw new ParticleEventsError("APS_SUBEMITTER_CYCLE", `Sub-emitter link '${link.id}' references itself.`);
        this.snapshots = new Map();
        this.nextContinuous = new Map();
        this.delayed = [];
        this.followers = [];
        this.frameSpawned = 0;
        this.detach = [];
        this.disposed = false;
        this.colorScratch = new Float32Array(4);
    }

    subscribe(type, listener) { return this.eventQueue.subscribe(type, listener); }
    unsubscribe(type, listener) { return this.eventQueue.unsubscribe(type, listener); }
    clearEvents() { return this.eventQueue.clear(); }

    attach(mainEmission) {
        if (!this.source.enabled) return this;
        if (mainEmission) this.detach.push(mainEmission.addPostSpawnInitializer((slot, particleId, state, _system, _sequence, overrides) => {
            const snapshot = this._snapshot(slot, particleId, state, true, overrides?.customData);
            this.snapshots.set(particleId, snapshot);
        }));
        this.detach.push(this.system.on("emit", (handle, particleId) => {
            // Emit is delivered after the system applies the spawn transform.
            const snapshot = this._snapshot(this.system.state.slotFor(handle), particleId, this.system.state, true, this.snapshots.get(particleId)?.customData);
            this.snapshots.set(particleId, snapshot);
            this.eventQueue.enqueue("particle-birth", { particleId, snapshot }, this.system.time);
            this._scheduleLinks("birth", snapshot);
        }));
        const reset = () => {
            this.delayed.length = 0; this.followers.length = 0; this.snapshots.clear(); this.nextContinuous.clear();
            for (const link of this.links) link.spawned = 0;
            this.eventQueue.clear(); this.frameSpawned = 0;
        };
        this.detach.push(this.system.on("restart", reset), this.system.on("clear", reset));
        const lifecycle = [["play", "system-play"], ["restart", "system-restart"], ["loop", "system-loop"]];
        for (const [event, type] of lifecycle) this.detach.push(this.system.on(event, value => this.eventQueue.enqueue(type, { value }, this.system.time)));
        this.detach.push(this.system.on("complete", value => {
            this.eventQueue.enqueue("system-complete", { value }, this.system.time);
            this.frameSpawned = 0;
            while (this.delayed.length && this.delayed[0].due <= this.system.time + Number.EPSILON && this.frameSpawned < this.source.spawnBudget) this._spawn(this.delayed.shift());
            this.eventQueue.flush();
        }));
        this.detach.push(this.system.on("particle-death", (_handle, particleId) => {
            const snapshot = this.snapshots.get(particleId) ?? { particleId };
            this.eventQueue.enqueue("particle-death", { particleId, snapshot }, this.system.time);
            this._scheduleLinks("death", snapshot);
            this.snapshots.delete(particleId);
            for (const key of this.nextContinuous.keys()) if (key.startsWith(`${particleId}:`)) this.nextContinuous.delete(key);
        }));
        this.detach.push(addModuleEvaluator(this.system, "subEmitters", (_system, delta) => this.update(delta)));
        return this;
    }

    recordBurst(payload) { this.eventQueue.enqueue("burst", payload, payload.time ?? this.system.time); }
    handleExternalEvent(type, handle, colliderId, payload = {}) {
        if (!this.source.enabled || this.disposed) return false;
        const slot = this.system.state.slotFor(handle);
        const particleId = slot >= 0 ? this.system.state.particleIdForSlot(slot) : payload.particleId;
        const snapshot = slot >= 0 ? this._snapshot(slot, particleId, this.system.state) : this.snapshots.get(particleId) ?? { particleId };
        const event = type === "trigger" ? "trigger" : "collision";
        this.eventQueue.enqueue(`particle-${event}`, { particleId, colliderId, snapshot, ...payload }, this.system.time);
        this._scheduleLinks(event, snapshot, { colliderId, ...payload });
        return true;
    }
    emitCustom(name, payload = {}, particleId = null) {
        if (!this.source.enabled || this.disposed) return false;
        const snapshot = particleId === null ? { particleId: null } : (this.snapshots.get(particleId) ?? { particleId });
        this.eventQueue.enqueue("custom", { name, payload, particleId, snapshot }, this.system.time);
        this._scheduleLinks("custom", snapshot, { name, payload });
        return true;
    }

    _snapshot(slot, particleId, state, fromStart = false, customOverride) {
        const values = fromStart ? state.start : state.current;
        const current = state.current;
        unpackParticleColor(values.color[slot], this.colorScratch);
        return {
            particleId, parentParticleId: null,
            position: { x: values.positionX[slot], y: values.positionY[slot] },
            velocity: { x: values.velocityX[slot], y: values.velocityY[slot] },
            rotation: values.rotation[slot], size: { x: values.sizeX[slot], y: values.sizeY[slot] },
            color: Array.from(this.colorScratch),
            lifetimeRatio: fromStart ? 0 : (current.lifetime[slot] > 0 ? current.age[slot] / current.lifetime[slot] : 1),
            seed: current.randomSeed[slot], customData: customOverride ?? this.readCustomData?.(slot, particleId, state) ?? null
        };
    }

    _scheduleLinks(event, snapshot, extra = {}, onlyLink = null) {
        for (const link of this.links) {
            if (onlyLink && link !== onlyLink) continue;
            if (!link.enabled || link.event !== event || link.spawned >= link.maximumSpawn) continue;
            if (this.delayed.length >= this.source.eventBudget) break;
            const random = deterministicUnit(snapshot.seed ?? this.system.effectSeed, "sub-emitter", link.id, snapshot.particleId ?? 0, link.spawned);
            if (evaluateParticleValue(link.probability, snapshot.lifetimeRatio ?? 0, random) < random) continue;
            const count = Math.max(0, Math.floor(evaluateParticleValue(link.count, snapshot.lifetimeRatio ?? 0, random)));
            const request = { due: this.system.time + link.delay, link, snapshot, extra, count, sequence: this.eventQueue.sequence++ };
            this.delayed.push(request);
        }
        this.delayed.sort((a, b) => a.due - b.due || a.sequence - b.sequence);
    }

    _inherit(link, snapshot) {
        const payload = { parentParticleId: snapshot.particleId, linkId: link.id };
        for (const key of ["position", "velocity", "rotation", "size", "color", "lifetimeRatio", "seed", "customData"]) if (link.inherit[key]) payload[key] = snapshot[key];
        return payload;
    }

    _spawn(request) {
        const available = Math.min(request.count, request.link.maximumSpawn - request.link.spawned, this.source.spawnBudget - this.frameSpawned);
        if (available <= 0) return 0;
        const inherited = this._inherit(request.link, request.snapshot);
        const result = this.spawnEffect?.({
            target: { subEffectId: request.link.subEffectId ?? null, systemId: request.link.systemId ?? null, emitterId: request.link.emitterId ?? null },
            count: available, inherited, parentParticleId: request.snapshot.particleId,
            ancestry: [...this.ancestry, this.effectId], depth: this.ancestry.length + 1, followParent: request.link.followParent, extra: request.extra,
            scheduledTime: request.due, startDelay: Math.max(0, request.due - this.system.time)
        }) ?? { spawned: 0, particleIds: [] };
        const spawned = Math.min(available, Math.max(0, Math.floor(result.spawned ?? result.particleIds?.length ?? 0)));
        request.link.spawned += spawned; this.frameSpawned += spawned;
        this.eventQueue.enqueue("sub-emitter-spawn", { linkId: request.link.id, parentParticleId: request.snapshot.particleId, childParticleIds: [...(result.particleIds ?? [])], count: spawned }, this.system.time);
        if (request.link.followParent && typeof result.setTransform === "function") this.followers.push({ parentParticleId: request.snapshot.particleId, setTransform: result.setTransform, dispose: result.dispose });
        return spawned;
    }

    update() {
        if (this.disposed) return null;
        this.frameSpawned = 0;
        const state = this.system.state;
        let slot = state.firstActiveSlot();
        while (slot !== -1) {
            const particleId = state.particleIdForSlot(slot);
            const snapshot = this._snapshot(slot, particleId, state);
            this.snapshots.set(particleId, snapshot);
            for (const link of this.links) if (link.enabled && link.event === "continuous") {
                const key = `${particleId}:${link.id}`; const next = this.nextContinuous.get(key) ?? this.system.time;
                if (this.system.time + Number.EPSILON >= next) {
                    this.eventQueue.enqueue("particle-continuous", { particleId, linkId: link.id, snapshot }, this.system.time);
                    this._scheduleLinks("continuous", snapshot, {}, link); this.nextContinuous.set(key, this.system.time + link.interval);
                }
            }
            slot = state.nextActiveSlot(slot);
        }
        while (this.delayed.length && this.delayed[0].due <= this.system.time + Number.EPSILON && this.frameSpawned < this.source.spawnBudget) this._spawn(this.delayed.shift());
        for (let index = this.followers.length - 1; index >= 0; index -= 1) {
            const follower = this.followers[index]; const snapshot = this.snapshots.get(follower.parentParticleId);
            if (snapshot && follower.setTransform(snapshot.position, snapshot.rotation, snapshot.size) !== false) continue;
            else { follower.dispose?.(); this.followers.splice(index, 1); }
        }
        return this.eventQueue.flush();
    }

    dispose() {
        if (this.disposed) return;
        for (const detach of this.detach.splice(0)) detach?.();
        for (const follower of this.followers) follower.dispose?.();
        this.followers.length = 0; this.delayed.length = 0; this.snapshots.clear(); this.nextContinuous.clear();
        if (this.ownsQueue) this.eventQueue.dispose();
        this.disposed = true;
    }
}
