const NATIVE_TMX_OBJECT_KEYS = new Set([
    "capsule",
    "class",
    "ellipse",
    "gid",
    "height",
    "id",
    "name",
    "opacity",
    "point",
    "polygon",
    "polyline",
    "properties",
    "propertytypes",
    "rotation",
    "template",
    "text",
    "tintcolor",
    "type",
    "visible",
    "width",
    "x",
    "y"
]);

const installedLevelManagers = new WeakSet();
const installedTileMapPrototypes = new WeakSet();
const EDITOR_LAYER_NAME = "__melonEditorLayerName";

function propertyType(value) {
    if (typeof value === "boolean") return "bool";
    if (typeof value === "number") return Number.isInteger(value) ? "int" : "float";
    return "string";
}

function normalizeEditorValue(name, value) {
    if (name !== "inspectors" || !value || typeof value !== "object" || Array.isArray(value)) {
        return value;
    }

    const inspectors = { ...value };
    if (Object.prototype.hasOwnProperty.call(inspectors, "rotate")) {
        const degrees = Number(inspectors.rotate);
        inspectors.rotate = Number.isFinite(degrees) ? degrees * Math.PI / 180 : 0;
    }
    return inspectors;
}

function setTMXProperty(object, name, value) {
    if (Array.isArray(object.properties)) {
        const existing = object.properties.find(property => property?.name === name);
        if (existing) {
            existing.type = propertyType(value);
            existing.value = value;
        } else {
            object.properties.push({ name, type: propertyType(value), value });
        }
        return;
    }

    if (!object.properties || typeof object.properties !== "object") {
        object.properties = {};
    }
    if (!object.propertytypes || typeof object.propertytypes !== "object") {
        object.propertytypes = {};
    }
    object.properties[name] = value;
    object.propertytypes[name] = propertyType(value);
}

/**
 * Promote Melon Editor metadata stored beside the standard Tiled object fields
 * into TMX properties. melonJS 19 only forwards TMX properties to the object
 * factory, while the Editor's 17.4 fork also forwarded these top-level fields.
 */
export function normalizeMelonEditorTMXObject(object) {
    if (!object || typeof object !== "object" || Array.isArray(object)) return object;

    for (const [name, rawValue] of Object.entries(object)) {
        if (NATIVE_TMX_OBJECT_KEYS.has(name) || rawValue === undefined) continue;
        setTMXProperty(object, name, normalizeEditorValue(name, rawValue));
    }
    return object;
}

function forwardObjectLayerName(layer, object) {
    const generatedFactoryName = typeof object?.name === "string" && object.name.length > 0
        ? object.name
        : undefined;
    const usesStructuralFactory = typeof object?.text === "object" || typeof object?.tile === "object";
    const editorLayerName = typeof object?.[EDITOR_LAYER_NAME] === "string"
        ? object[EDITOR_LAYER_NAME]
        : layer?.name;
    if (
        typeof editorLayerName !== "string" ||
        editorLayerName.length === 0 ||
        (!generatedFactoryName && !usesStructuralFactory) ||
        (typeof object.class === "string" && object.class.length > 0)
    ) {
        return;
    }

    // The Editor stores the pool/factory name on the TMX object and the
    // instance name on its containing object layer. The 17.4 Editor fork
    // assigned group.name after instantiation, while upstream melonJS 20 no
    // longer does. Preserve the factory in `class` (resolved first by v20),
    // then let the TMX property parser pass the layer name to the constructor.
    if (usesStructuralFactory) {
        object.class = typeof object.text === "object" ? "text" : "tile";
        object.name = editorLayerName;
    } else if (generatedFactoryName) {
        object.class = generatedFactoryName;
    }
    setTMXProperty(object, "name", editorLayerName);
    setTMXProperty(object, EDITOR_LAYER_NAME, editorLayerName);
}

function installObjectLayerNameCompatibility(engine) {
    const prototype = engine?.TMXTileMap?.prototype;
    if (
        !prototype ||
        installedTileMapPrototypes.has(prototype) ||
        typeof prototype.getObjects !== "function"
    ) {
        return false;
    }

    function applyLayerName(settings, object) {
        const layerName = settings?.[EDITOR_LAYER_NAME]
            ?? settings?.text?.[EDITOR_LAYER_NAME];
        if (object && typeof layerName === "string" && layerName.length > 0) {
            object.name = layerName;
        }
    }

    const getObjects = prototype.getObjects;
    prototype.getObjects = function melonEditorCompatibleGetObjects(flatten) {
        // Parse first so objectGroups contains the TMX settings paired with
        // every instance returned by the native factory implementation.
        this.readMapObjects(this.data);
        const objects = getObjects.call(this, flatten);

        if (flatten !== false) {
            let objectIndex = 0;
            for (const group of this.objectGroups) {
                for (const settings of group.objects) {
                    applyLayerName(settings, objects[objectIndex++]);
                }
            }
        } else {
            let containerIndex = 0;
            for (const group of this.objectGroups) {
                if (!Array.isArray(group.objects) || group.objects.length === 0) continue;
                const container = objects[containerIndex++];
                const children = container?.getChildren?.() ?? container?.children ?? [];
                group.objects.forEach((settings, index) => {
                    applyLayerName(settings, children[index]);
                });
            }
        }
        return objects;
    };
    installedTileMapPrototypes.add(prototype);
    return true;
}

function normalizeLayer(layer, options) {
    if (!layer || typeof layer !== "object") return;
    if (Array.isArray(layer.objects)) {
        layer.objects.forEach(object => {
            normalizeMelonEditorTMXObject(object);
            if (options.forwardObjectLayerName === true) {
                forwardObjectLayerName(layer, object);
            }
        });
    }
    if (Array.isArray(layer.layers)) {
        layer.layers.forEach(child => normalizeLayer(child, options));
    }
}

export function normalizeMelonEditorTMXMap(map, options = {}) {
    if (!map || typeof map !== "object") return map;
    if (Array.isArray(map.layers)) {
        map.layers.forEach(layer => normalizeLayer(layer, options));
    }
    return map;
}

/** Install the compatibility step at the public level-loading boundary. */
export function installMelonEditorTMXCompatibility(engine, options = {}) {
    if (options.forwardObjectLayerName === true) {
        installObjectLayerNameCompatibility(engine);
    }
    const level = engine?.level;
    if (
        !level ||
        installedLevelManagers.has(level) ||
        typeof level.add !== "function" ||
        typeof engine?.loader?.getTMX !== "function"
    ) {
        return false;
    }

    const addLevel = level.add;
    level.add = function melonEditorCompatibleLevelAdd(format, levelId, callback) {
        if (String(format).toLowerCase() === "tmx") {
            normalizeMelonEditorTMXMap(engine.loader.getTMX(levelId), options);
        }
        return addLevel.call(this, format, levelId, callback);
    };
    installedLevelManagers.add(level);
    return true;
}
