export function requireObject(value, label = "object") {
    if (!value || typeof value !== "object") {
        throw new TypeError(`Melon Runtime: ${label} tidak valid.`);
    }
    return value;
}

export function requireFunction(value, label = "callback") {
    if (typeof value !== "function") {
        throw new TypeError(`Melon Runtime: ${label} harus berupa fungsi.`);
    }
    return value;
}

export function finiteNumber(value, fallback = 0) {
    const number = Number(value);
    return Number.isFinite(number) ? number : fallback;
}

export function clamp(value, min, max) {
    return Math.min(Math.max(value, min), max);
}
