import { createMelonJsAdapter } from "./melonjs-17.4.0.js";
import { installBuiltinCollisionCompatibility } from "../compat/melon-editor-builtin-collision.js";
import { installMelonEditorChildCompatibility } from "../compat/melon-editor-children.js";
import { installRenderableEventsCompatibility } from "../compat/melon-editor-renderable-events.js";
import { installMelonEditorTMXCompatibility } from "../compat/melon-editor-tmx.js";

export function restartMelonJs20Level(engine, application, stage) {
    const activeStage = stage ?? engine?.state?.current?.();
    if (
        !activeStage
        || typeof activeStage.destroy !== "function"
        || typeof activeStage.reset !== "function"
    ) {
        return false;
    }

    const defer = engine?.utils?.function?.defer
        ?? ((callback) => globalThis.setTimeout(callback, 0));
    defer(() => {
        // Do not reset a stale stage when another scene change won the race.
        if (
            typeof engine?.state?.current === "function"
            && engine.state.current() !== activeStage
        ) {
            return;
        }

        activeStage.destroy(application);
        activeStage.reset(application);
        engine?.event?.emit?.(engine.event.STATE_CHANGE);
    });
    return true;
}

export function createMelonJs20Adapter(engine, options = {}) {
    const application = options.application ?? engine.game;
    const adapter = createMelonJsAdapter(engine, {
        ...options,
        engineVersion: "20.0.0",
        minimumEngineMajor: 20,
        adapterName: "melonjs-20.0.0",
        applicationInstance: true,
        collisionLifecycle: "modern-callbacks",
        persistentTimers: false,
        portableShapeActivation: true
    });
    const configure = adapter.configure;
    const reloadScene = adapter.reloadScene;
    adapter.configure = runtimeOptions => {
        const result = configure.call(adapter, runtimeOptions);
        installBuiltinCollisionCompatibility(
            engine,
            application?.world?.adapter?.detector
        );
        return result;
    };
    adapter.reloadScene = reloadOptions => {
        const currentName = engine.level.getCurrentLevelId();
        const currentStage = currentName ? engine.state.get(currentName) : undefined;
        if (currentStage) {
            return restartMelonJs20Level(engine, application, currentStage);
        }
        return reloadScene.call(adapter, reloadOptions);
    };
    installBuiltinCollisionCompatibility(
        engine,
        application?.world?.adapter?.detector
    );
    installMelonEditorChildCompatibility(engine);
    installRenderableEventsCompatibility(engine);
    installMelonEditorTMXCompatibility(engine, {
        forwardObjectLayerName: true
    });
    return adapter;
}
