import { ParticlePreviewSeedController } from "./deterministic-random.js";
import { createParticleSystem2DFromEmitter } from "./particle-runtime-modules.js";
import { particleShapeGizmoData } from "./particle-shapes.js";

export class ParticlePreviewError extends Error {
    constructor(code, message, details = {}) { super(message); this.name = "ParticlePreviewError"; this.code = code; this.details = details; }
}

const nowDefault = () => globalThis.performance?.now?.() ?? Date.now();
const finite = (value, fallback) => Number.isFinite(value) ? value : fallback;

export class ParticlePreviewController {
    constructor(compiledEffect, systemId, emitterId, options = {}) {
        if (!compiledEffect?.asset || compiledEffect.disposed) throw new ParticlePreviewError("APS_PREVIEW_INVALID_EFFECT", "A live compiled ParticleEffect2D is required.");
        this.compiledEffect = compiledEffect; this.systemId = systemId; this.emitterId = emitterId; this.options = { ...options };
        this.now = options.now ?? nowDefault; this.frameStepSeconds = Math.max(1 / 1000, options.frameStepSeconds ?? 1 / 60);
        this.playbackSpeed = Math.max(0, finite(options.playbackSpeed, 1)); this.loopRange = null;
        this.seed = options.seedController ?? new ParticlePreviewSeedController({ seed: options.seed ?? compiledEffect.asset.effect?.randomSeed ?? 1, locked: options.seedLocked !== false });
        this.camera = { x: 0, y: 0, zoom: 1 }; this.background = { type: "checker", color: "#20242a", imageId: null };
        this.target = { backend: options.backend ?? "canvas2d", platform: options.platform ?? "web", quality: options.quality ?? "high" };
        this.gizmos = { shape: true, bounds: true, velocity: false, collisionNormals: false, forceFields: false, heatmap: false };
        this.roadmap = Object.freeze({ capture: ["gif", "video", "spritesheet"], status: "non-blocking-roadmap" });
        this.profile = { active: 0, spawned: 0, died: 0, cpuUpdateMs: 0, renderMs: 0, drawCalls: 0, memoryBytes: 0, overdrawPeak: 0, frames: 0 };
        this.errors = []; this.runtime = null; this.detach = []; this.rebuild();
    }

    _runtimeOptions() { return { ...(this.options.runtimeOptions ?? {}), rendererBackend: this.target.backend, quality: this.target.quality, seedOptions: { ...(this.options.seedOptions ?? {}), previewSeedController: this.seed } }; }
    rebuild() {
        this._disposeRuntime(); this.errors.length = 0;
        Object.assign(this.profile, { active: 0, spawned: 0, died: 0, cpuUpdateMs: 0, renderMs: 0, drawCalls: 0, memoryBytes: 0, overdrawPeak: 0, frames: 0 });
        try {
            this.runtime = createParticleSystem2DFromEmitter(this.compiledEffect, this.systemId, this.emitterId, this._runtimeOptions());
            this.runtime.system.stop("clear");
            this.detach.push(this.runtime.system.on("emit", () => { this.profile.spawned += 1; }));
            this.detach.push(this.runtime.system.on("particle-death", () => { this.profile.died += 1; }));
        } catch (error) { this.errors.push({ code: error.code ?? "APS_PREVIEW_RUNTIME_ERROR", message: error.message, severity: "error" }); throw error; }
        return this;
    }
    play() { const system = this.runtime.system; system.paused ? system.resume() : system.play({ restart: system.completed }); return this; }
    pause() { this.runtime.system.pause(); return this; }
    stop() { this.runtime.system.stop("clear"); return this; }
    restart() { this.runtime.system.restart(); return this; }
    frameStep() { const wasPlaying = this.runtime.system.playing; if (!wasPlaying) this.runtime.system.play(); this.step(this.frameStepSeconds, { force: true }); this.runtime.system.pause(); return this.snapshot(); }
    scrub(seconds) { this.runtime.system.simulate(Math.max(0, finite(seconds, 0)), { restart: true }); return this.snapshot(); }
    setLoopRange(start, end) { if (!Number.isFinite(start) || !Number.isFinite(end) || start < 0 || end <= start) throw new ParticlePreviewError("APS_PREVIEW_INVALID_LOOP", "Loop range requires finite start < end."); this.loopRange = { start, end }; return this; }
    clearLoopRange() { this.loopRange = null; return this; }
    setPlaybackSpeed(speed) { if (!Number.isFinite(speed) || speed < 0) throw new ParticlePreviewError("APS_PREVIEW_INVALID_SPEED", "Playback speed must be finite and non-negative."); this.playbackSpeed = speed; return this; }
    setTimeMode(mode) { if (!["scaled", "unscaled"].includes(mode)) throw new ParticlePreviewError("APS_PREVIEW_INVALID_TIME_MODE", `Unknown time mode '${mode}'.`); this.runtime.system.timeMode = mode; return this; }
    lockSeed(seed = this.seed.seed) { this.seed.lock(seed); return this.rebuild(); }
    unlockSeed() { this.seed.unlock(); return this; }
    randomizeSeed(entropy) { if (typeof entropy === "undefined") throw new ParticlePreviewError("APS_PREVIEW_ENTROPY_REQUIRED", "Seed randomize requires explicit entropy."); this.seed.randomize(entropy); return this.rebuild(); }
    setTarget(target = {}) { Object.assign(this.target, target); return this.rebuild(); }
    setCamera(camera = {}) { this.camera.x = finite(camera.x, this.camera.x); this.camera.y = finite(camera.y, this.camera.y); this.camera.zoom = Math.max(0.01, finite(camera.zoom, this.camera.zoom)); return this; }
    panCamera(x, y) { this.camera.x += finite(x, 0); this.camera.y += finite(y, 0); return this; }
    zoomCamera(factor) { this.camera.zoom = Math.max(0.01, Math.min(64, this.camera.zoom * finite(factor, 1))); return this; }
    setBackground(background = {}) { Object.assign(this.background, background); return this; }
    setGizmo(name, enabled) { if (!(name in this.gizmos)) throw new ParticlePreviewError("APS_PREVIEW_INVALID_GIZMO", `Unknown gizmo '${name}'.`); this.gizmos[name] = enabled === true; return this; }
    step(deltaSeconds, context = {}) {
        const system = this.runtime.system; if (!system.playing && context.force !== true) return this.snapshot();
        const start = this.now(); const delta = Math.max(0, finite(deltaSeconds, 0)) * this.playbackSpeed;
        const transform = context.transform ?? this.options.movingEmitter?.(system.time + delta) ?? undefined;
        system.step(delta, { timeScale: context.timeScale, visible: context.visible, transform });
        if (this.loopRange && system.time + Number.EPSILON >= this.loopRange.end) { const playing = system.playing; this.scrub(this.loopRange.start); if (playing) system.resume(); }
        this.profile.cpuUpdateMs = this.now() - start; this.profile.frames += 1; this._refreshProfile(); return this.snapshot();
    }
    render(renderBatch = this.options.renderBatch) {
        const start = this.now(); const batch = this.runtime.renderer.buildBatch();
        const trailBatch = this.runtime.trails.source.enabled && batch?.primitive !== "trail-strip-batch" ? this.runtime.trails.buildGeometry() : null;
        if (trailBatch?.count && renderBatch) renderBatch(trailBatch, this.viewState());
        if (batch?.count && renderBatch) renderBatch(batch, this.viewState());
        this.profile.renderMs = this.now() - start; this.profile.drawCalls = (batch?.drawCallGroups ?? 0) + (trailBatch?.drawCallGroups ?? 0); this.profile.overdrawPeak = this.approximateOverdraw(batch).peak; this._refreshProfile(); return batch;
    }
    _refreshProfile() { const state = this.runtime.system.state; this.profile.active = state.activeCount; this.profile.memoryBytes = state.memoryStats().totalBytes; }
    approximateOverdraw(batch = this.runtime.renderer.batch, options = {}) {
        const width = Math.max(1, Math.floor(options.width ?? 32)); const height = Math.max(1, Math.floor(options.height ?? 32)); const cells = new Uint16Array(width * height);
        if (!batch?.count) return { width, height, cells, peak: 0 };
        const bounds = batch.bounds; const spanX = Math.max(1e-6, bounds.maxX - bounds.minX); const spanY = Math.max(1e-6, bounds.maxY - bounds.minY); let peak = 0;
        const stride = batch.primitive === "trail-strip-batch" ? 3 : 6; const positions = batch.primitive === "trail-strip-batch" ? batch.vertices : batch.transforms;
        for (let index = 0; index < batch.count; index += 1) { const offset = index * stride; const x = Math.max(0, Math.min(width - 1, Math.floor((positions[offset] - bounds.minX) / spanX * width))); const y = Math.max(0, Math.min(height - 1, Math.floor((positions[offset + 1] - bounds.minY) / spanY * height))); const value = ++cells[y * width + x]; if (value > peak) peak = value; }
        return { width, height, cells, peak };
    }
    autoCalculateBounds(options = {}) {
        const runtime = createParticleSystem2DFromEmitter(this.compiledEffect, this.systemId, this.emitterId, this._runtimeOptions()); const duration = Math.max(0, options.duration ?? runtime.system.duration); const step = Math.max(1 / 240, options.step ?? 1 / 60);
        const bounds = { minX: Infinity, minY: Infinity, maxX: -Infinity, maxY: -Infinity }; runtime.system.restart();
        for (let time = 0; time <= duration + Number.EPSILON; time += step) { runtime.system.step(step, { transform: this.options.movingEmitter?.(time) }); const current = runtime.renderer.visibilityBounds(); bounds.minX = Math.min(bounds.minX, current.minX); bounds.minY = Math.min(bounds.minY, current.minY); bounds.maxX = Math.max(bounds.maxX, current.maxX); bounds.maxY = Math.max(bounds.maxY, current.maxY); }
        runtime.dispose(); if (!Number.isFinite(bounds.minX)) return { minX: 0, minY: 0, maxX: 0, maxY: 0 }; return bounds;
    }
    simulationSpaceProbe(transform = { x: 10, y: 20, rotation: 30, scaleX: 1, scaleY: 1 }) { const system = this.runtime.system; const output = {}; for (const space of ["local", "world", "custom"]) { if (space === "custom") system.updateCustomTransform(transform); else system.updateTransform(transform); output[space] = Array.from(system.transformPoint(1, 0, space)); } return output; }
    gizmoSnapshot() { const batch = this.runtime.renderer.batch ?? this.runtime.renderer.buildBatch(); const state = this.runtime.system.state; const velocity = []; if (this.gizmos.velocity) for (let slot = state.firstActiveSlot(); slot !== -1; slot = state.nextActiveSlot(slot)) velocity.push({ particleId: state.particleIdForSlot(slot), x: state.current.positionX[slot], y: state.current.positionY[slot], vx: state.current.velocityX[slot], vy: state.current.velocityY[slot] }); return { enabled: { ...this.gizmos }, bounds: batch?.bounds ?? null, shape: this.runtime.shape ? particleShapeGizmoData(this.runtime.shape) : null, velocity, collisionNormals: this.runtime.collision?.lastBatch?.events ?? [], forceFields: this.runtime.noiseFields?.registry?.query?.(null, 0xFFFFFFFF, this.runtime.noiseFields.fields.maximum) ?? [] }; }
    diagnostics(capabilities) { const warnings = [...(this.runtime.renderer.warnings ?? []), ...(this.runtime.lights.warnings ?? [])]; const unsupported = capabilities?.simulation === "unsupported" ? [{ code: "APS_CAP_UNSUPPORTED", feature: "particle2D.simulation", severity: "error" }] : []; return { errors: [...this.errors, ...unsupported], warnings, target: { ...this.target } }; }
    viewState() { return { camera: { ...this.camera }, background: { ...this.background }, target: { ...this.target }, gizmos: this.gizmoSnapshot() }; }
    snapshot() { this._refreshProfile(); return { time: this.runtime.system.time, playbackState: this.runtime.system.playbackState, loopRange: this.loopRange && { ...this.loopRange }, seed: this.seed.saveState(), profile: { ...this.profile }, target: { ...this.target } }; }
    requestCapture(kind) { return Promise.resolve({ accepted: false, kind, status: this.roadmap.status }); }
    _disposeRuntime() { for (const detach of this.detach.splice(0)) detach?.(); this.runtime?.dispose(); this.runtime = null; }
    dispose() { this._disposeRuntime(); this.errors.length = 0; }
}

export function createParticlePreviewController(compiledEffect, systemId, emitterId, options) { return new ParticlePreviewController(compiledEffect, systemId, emitterId, options); }
