import { clamp, finiteNumber, requireFunction, requireObject } from "../internal/guards.js";

function targetOf(object) {
    return object.renderable ?? object;
}

function invoke(object, names, ...args) {
    for (const name of names) {
        if (typeof object?.[name] === "function") return object[name](...args);
    }
    return undefined;
}

function setVector(vector, x, y) {
    if (typeof vector?.set === "function") vector.set(x, y);
    else if (vector) Object.assign(vector, { x, y });
}

export function createRenderableModule({ adapter }) {
    return {
        setOpacity(object, value) {
            return adapter.setOpacity(requireObject(object), clamp(finiteNumber(value, 1), 0, 1));
        },
        opacity(object) {
            const target = targetOf(requireObject(object));
            return finiteNumber(target.getOpacity?.() ?? target.opacity ?? target._opacity, 1);
        },
        setTint(object, color) {
            return adapter.setSpriteTint(requireObject(object), String(color));
        },
        clearTint(object) {
            return adapter.setSpriteTint(requireObject(object), "#ffffff");
        },
        setBlendMode(object, mode = "normal") {
            return adapter.setSpriteBlendMode(requireObject(object), String(mode || "normal"));
        },
        setAnchor(object, x = 0.5, y = 0.5) {
            return adapter.setSpriteAnchor(requireObject(object), finiteNumber(x, 0.5), finiteNumber(y, 0.5));
        },
        setSize(object, width, height) {
            const target = targetOf(requireObject(object));
            const nextWidth = Math.max(0, finiteNumber(width));
            const nextHeight = Math.max(0, finiteNumber(height));
            if (typeof target.resize === "function") target.resize(nextWidth, nextHeight);
            else {
                target.width = nextWidth;
                target.height = nextHeight;
                if ("_width" in target) target._width = nextWidth;
                if ("_height" in target) target._height = nextHeight;
            }
            return object;
        },
        size(object, axis = "width") {
            const target = targetOf(requireObject(object));
            return finiteNumber(axis === "height" ? target.height ?? target._height : target.width ?? target._width);
        },
        setVisible(object, visible = true) {
            const target = targetOf(requireObject(object));
            target.visible = visible === true;
            return object;
        },
        isVisible(object) {
            return targetOf(requireObject(object)).visible !== false;
        },
        setFloating(object, floating = true) {
            targetOf(requireObject(object)).floating = floating === true;
            return object;
        },
        setPrimitive(object, property, value) {
            const target = targetOf(requireObject(object));
            const key = property === "roundness" ? "roundLevel" : property;
            target[key] = key === "roundLevel" ? Math.max(0, finiteNumber(value)) : value;
            target.isDirty = true;
            return object;
        }
    };
}

export function createVideoModule() {
    const videoTarget = object => {
        const target = requireObject(object);
        return target.video ?? target.image ?? targetOf(target);
    };
    return {
        control(object, action) {
            const target = videoTarget(object);
            if (action === "reset") {
                target.currentTime = 0;
                return object;
            }
            if (action === "stop") {
                invoke(target, ["stop", "pause"]);
                if ("currentTime" in target) target.currentTime = 0;
                return object;
            }
            invoke(target, action === "play" || action === "resume" ? ["play", "resume"] : ["pause"]);
            return object;
        },
        seek(object, seconds) {
            videoTarget(object).currentTime = Math.max(0, finiteNumber(seconds));
            return object;
        },
        time(object, kind = "currentTime") {
            return finiteNumber(videoTarget(object)[kind]);
        },
        setOption(object, option, value) {
            const target = videoTarget(object);
            target[option] = option === "volume"
                ? clamp(finiteNumber(value, 1), 0, 1)
                : option === "playbackRate" ? Math.max(0.01, finiteNumber(value, 1)) : value === true;
            return object;
        },
        status(object, kind = "playing") {
            const target = videoTarget(object);
            if (kind === "ended") return target.ended === true;
            if (kind === "muted") return target.muted === true;
            return target.paused !== true && target.ended !== true;
        }
    };
}

function writeText(object, value, append) {
    const target = targetOf(requireObject(object));
    const next = append ? String(target.text ?? "") + String(value) : String(value);
    if (typeof target.setText === "function") target.setText(next);
    else target.text = next;
    return object;
}

function createTextLikeModule(bitmap = false) {
    return {
        set(object, value) { return writeText(object, value, false); },
        append(object, value) { return writeText(object, value, true); },
        get(object) { return String(targetOf(requireObject(object)).text ?? ""); },
        setStyle(object, property, value) {
            const target = targetOf(requireObject(object));
            const numeric = new Set(["fontSize", "size", "lineWidth", "lineHeight", "wordWrapWidth"]);
            const next = numeric.has(property) ? finiteNumber(value) : value;
            if (bitmap && property === "size" && typeof target.resize === "function") {
                target.resize(Math.max(0, next));
            } else if (!bitmap && property === "font" && typeof target.setFont === "function") {
                target.setFont(String(next), target.fontSize);
            } else if (!bitmap && property === "fontSize" && typeof target.setFont === "function") {
                target.setFont(String(target.font || "Arial").replace(/^(?:(?:bold|italic)\s+)+/, ""), Math.max(0, next));
            } else if (!bitmap && (property === "fillStyle" || property === "strokeStyle") && typeof target[property]?.parseCSS === "function") {
                target[property].parseCSS(String(next));
            } else if (!bitmap && (property === "bold" || property === "italic")) {
                const enabled = next === true || next === "true" || next === "TRUE" || next === 1;
                if (enabled) target[property]?.();
                else {
                    const token = new RegExp(`(^|\\s)${property}(?=\\s|$)`, "g");
                    target.font = String(target.font || "").replace(token, " ").replace(/\s+/g, " ").trim();
                }
            } else {
                target[property] = next;
            }
            target.isDirty = true;
            if (typeof target.setText === "function" && !["font", "fontSize", "size"].includes(property)) {
                target.setText(target.text ?? "");
            }
            return object;
        },
        measure(object, axis = "width") {
            const target = targetOf(requireObject(object));
            return finiteNumber(target.measureText?.()?.[axis] ?? target.getBounds?.()?.[axis] ?? target[axis]);
        }
    };
}

export function createTextModule() { return createTextLikeModule(false); }
export function createBitmapTextModule() { return createTextLikeModule(true); }

export function createTriggerModule({ adapter }) {
    return {
        setEnabled(object, enabled = true) {
            const target = requireObject(object);
            target.triggerEnabled = enabled === true;
            const shapes = target.body?.shapes ?? [];
            for (let index = 0; index < shapes.length; index++) {
                if (typeof adapter.setShapeActive === "function") adapter.setShapeActive(target, index, enabled === true);
                else shapes[index].isActive = enabled === true;
            }
            return object;
        },
        isEnabled(object) { return requireObject(object).triggerEnabled !== false; },
        reset(object) { requireObject(object).onceOnly = false; return object; },
        fire(object, activator = null) {
            const target = requireObject(object);
            if (target.triggerEnabled === false) return false;
            if (typeof target.onCollisionStart === "function") return target.onCollisionStart({}, activator);
            if (typeof target.onCollision === "function") return target.onCollision({}, activator);
            return invoke(target, ["activate", "trigger"], activator) ?? false;
        }
    };
}

export function createDraggableModule() {
    return {
        setEnabled(object, enabled = true) { requireObject(object).dragEnabled = enabled === true; return object; },
        isDragging(object) { return requireObject(object).dragging === true; },
        cancel(object) { const target = requireObject(object); invoke(target, ["dragEnd"]); target.dragging = false; return object; },
        setAxis(object, axis = "both") { requireObject(object).dragAxis = axis; return object; },
        setBounds(object, x, y, width, height) {
            requireObject(object).dragBounds = { x: finiteNumber(x), y: finiteNumber(y), width: Math.max(0, finiteNumber(width)), height: Math.max(0, finiteNumber(height)) };
            return object;
        },
        setSnap(object, x, y = x) { requireObject(object).dragSnap = { x: Math.max(0, finiteNumber(x)), y: Math.max(0, finiteNumber(y)) }; return object; }
    };
}

export function createUiModule() {
    return {
        setEnabled(object, enabled = true) { const target = requireObject(object); target.isEnable = enabled === true; target.enabled = enabled === true; return object; },
        isEnabled(object) { const target = requireObject(object); return target.isEnable !== false && target.enabled !== false; },
        add(object, child, z) { requireObject(object).addChild?.(requireObject(child, "child"), z); return child; },
        remove(object, child) { return requireObject(object).removeChild?.(requireObject(child, "child")) ?? false; },
        find(object, name) { const target = requireObject(object); return target.getChildByName?.(String(name)) ?? (target.children ?? []).find(child => child?.name === String(name)) ?? null; },
        count(object) { return requireObject(object).children?.length ?? 0; },
        clear(object) { const target = requireObject(object); for (const child of [...(target.children ?? [])]) { if (typeof target.removeChildNow === "function") target.removeChildNow(child); else target.removeChild?.(child); } return object; }
    };
}

export function createSliderModule() {
    const watchers = new WeakMap();
    const bridgedButtons = new WeakSet();
    const ensureEnabledBridge = target => {
        const button = target.sliderButton;
        if (!button || bridgedButtons.has(button)) return;
        bridgedButtons.add(button);
        for (const method of ["dragStart", "dragMove"]) {
            const original = button[method];
            if (typeof original !== "function") continue;
            button[method] = function (...args) {
                if (target.sliderEnabled === false) return false;
                return original.apply(this, args);
            };
        }
    };
    const ensureWatcherBridge = target => {
        if (watchers.has(target)) return watchers.get(target);
        const callbacks = new Set();
        watchers.set(target, callbacks);
        const setter = target.setValueInternal;
        if (typeof setter === "function") {
            target.setValueInternal = function (...args) {
                const previous = this.value ?? this._value;
                const result = setter.apply(this, args);
                const next = this.value ?? this._value;
                if (next !== previous) callbacks.forEach(callback => callback(next, previous));
                return result;
            };
        }
        return callbacks;
    };
    return {
        setValue(object, value) { const target = requireObject(object); if (typeof target.setValueInternal === "function") target.setValueInternal(finiteNumber(value)); else target.value = finiteNumber(value); return object; },
        value(object) { return finiteNumber(requireObject(object).value ?? object._value); },
        setRange(object, min, max) { const target = requireObject(object); target._minValue = finiteNumber(min); target._maxValue = Math.max(target._minValue, finiteNumber(max)); this.setValue(target, target._value); return object; },
        percent(object) { const target = requireObject(object); const range = finiteNumber(target._maxValue) - finiteNumber(target._minValue); return range === 0 ? 0 : clamp((finiteNumber(target.value ?? target._value) - finiteNumber(target._minValue)) / range, 0, 1); },
        setEnabled(object, enabled = true) { const target = requireObject(object); ensureEnabledBridge(target); target.sliderEnabled = enabled === true; if (target.sliderButton) { target.sliderButton.isEnable = enabled === true; if (!enabled) { target.sliderButton.dragging = false; } } return object; },
        onChange(object, callback) { const target = requireObject(object); requireFunction(callback); ensureWatcherBridge(target).add(callback); return callback; }
    };
}

export function createTrailModule() {
    return {
        setTarget(object, target) { requireObject(object).target = requireObject(target, "target"); return object; },
        addPoint(object, x, y) { const target = requireObject(object); target.addPoint?.(finiteNumber(x), finiteNumber(y)); return object; },
        clear(object) { requireObject(object).clear?.(); return object; },
        configure(object, property, value) { const target = requireObject(object); target[property] = Math.max(0, finiteNumber(value)); return object; },
        pointCount(object) { return requireObject(object)._points?.length ?? object.points?.length ?? 0; }
    };
}

export function createLightModule() {
    return {
        setColor(object, color) { const target = requireObject(object); if (typeof target.color?.parseCSS === "function") target.color.parseCSS(String(color)); else target.color = String(color); return this.refresh(target); },
        setRadius(object, x, y = x) { const target = requireObject(object); target.radiusX = Math.max(0, finiteNumber(x)); target.radiusY = Math.max(0, finiteNumber(y)); return this.refresh(target); },
        setProperty(object, property, value) { const target = requireObject(object); const destination = property in (target.gradientSettings ?? {}) ? target.gradientSettings : target; destination[property] = typeof value === "number" ? finiteNumber(value) : value; return this.refresh(target); },
        refresh(object) { const target = requireObject(object); invoke(target, ["refreshLightGradient", "refreshGradient", "createGradient"]); target.isDirty = true; return object; }
    };
}

export function createParticleEmitterModule() {
    return {
        burst(object, total) { requireObject(object).burstParticles?.(Math.max(0, Math.trunc(finiteNumber(total)))); return object; },
        stream(object, duration) { requireObject(object).streamParticles?.(Math.max(0, finiteNumber(duration))); return object; },
        stop(object) { requireObject(object).stopStream?.(); return object; },
        add(object, count) { requireObject(object).addParticles?.(Math.max(0, Math.trunc(finiteNumber(count)))); return object; },
        reset(object) { requireObject(object).reset?.(); return object; },
        isRunning(object) { const target = requireObject(object); return target.isRunning?.() === true || target._stream === true; }
    };
}

export function createAudioSourceModule() {
    return {
        control(object, action) { const target = requireObject(object); const methods = { play: ["playAudio", "play"], stop: ["stopAudio", "stop"], pause: ["pauseAudio", "pause"], resume: ["resumeAudio", "resume"], mute: ["muteAudio", "mute"], unmute: ["unmuteAudio", "unmute"] }; invoke(target, methods[action] ?? []); return object; },
        setProperty(object, property, value) { const target = requireObject(object); target[property] = property === "audioVolume" ? clamp(finiteNumber(value, 1), 0, 1) : finiteNumber(value); target.applyAudioSettings?.(); return object; },
        status(object, kind = "playing") { const target = requireObject(object); return kind === "muted" ? target.isAudioMuted === true : kind === "paused" ? target.isAudioPaused === true : target.isAudioPlaying === true; },
        setPosition(object, x, y, z = 0) { const target = requireObject(object); if (typeof target.setSoundPosition === "function") target.setSoundPosition(finiteNumber(x), finiteNumber(y), finiteNumber(z)); else setVector(target.soundPosition ?? target.pos, finiteNumber(x), finiteNumber(y)); return object; },
        setSpatial(object, property, value) { requireObject(object)[property] = finiteNumber(value); return object; }
    };
}

export function createSprite25Module() {
    return {
        setLightingEnabled(object, enabled = true) { const target = targetOf(requireObject(object)); target.lightingEnabled = enabled === true; if (target.lightShader) target.lightShader.enabled = enabled === true; return object; },
        setLightHeight(object, height) { const target = targetOf(requireObject(object)); target.lightHeight = finiteNumber(height); target.lightShader?.setUniform?.("uHeight", target.lightHeight); return object; }
    };
}
