import * as engine from "./melonjs.module.js";
import { createTilemapSceneClass } from "../adapters/tilemap-scene.js";
export const TilemapScene = createTilemapSceneClass(engine);
import { createMelonRuntime, MELON_RUNTIME_VERSION } from "../index.js";
import { createMelonJs20Adapter } from "../adapters/melonjs-20.0.0.js";
import { createMelonJsParticleSystem2DBridge } from "../adapters/particle-system-2d-engine.js";
import {
    createCompatibleShaderEffect,
    createCompatibleShaderLoader,
    createCompatibleShaderManager,
    createMelonEditorClasses,
    installLegacyPoolAliases
} from "../compat/melon-editor-classes.js";
import { createMelonJs174ParticleClasses } from "../compat/melon-editor-particles.js";
import { createMelonJs174TextClasses, installMelonEditorTextFactories } from "../compat/melon-editor-text.js";
import { createMelonEditorAudioCompatibility } from "../compat/melon-editor-audio.js";

export * from "./melonjs.module.js";
export * from "../particle/particle-effect-2d.js";
export * from "../particle/particle-values.js";
export * from "../particle/deterministic-random.js";
export * from "../particle/particle-state.js";
export * from "../particle/particle-system-2d.js";
export * from "../particle/particle-main-emission.js";
export * from "../particle/particle-shapes.js";
export * from "../particle/particle-motion.js";
export * from "../particle/particle-runtime-modules.js";
export * from "../particle/particle-visual-properties.js";
export * from "../particle/particle-noise-fields.js";
export * from "../particle/particle-texture-renderer.js";
export * from "../particle/particle-collision.js";
export * from "../particle/particle-subemitters-events.js";
export * from "../particle/particle-trails-lights-custom.js";
export * from "../particle/particle-preview-profiler.js";
export * from "../particle/particle-performance.js";
export * from "../particle/particle-migration.js";
export * from "../particle/particle-presets.js";
export * from "../particle/particle-release.js";

const audio = createMelonEditorAudioCompatibility(engine);
const { AudioGroup, AudioMixer, GUI_Object, Slider, SliderButton } =
    createMelonEditorClasses(engine, { audio });
const {
    ParticleV174,
    ParticleEmitterV174,
    ParticleEmitterSettingsV174,
    configureParticleAssets
} = createMelonJs174ParticleClasses(engine);
const { TextV174, BitmapTextV174, TextMetricsV174 } = createMelonJs174TextClasses(engine);
const Text = TextV174;
const BitmapText = BitmapTextV174;
const TextMetrics = TextMetricsV174;
const TextV20 = engine.Text;
const BitmapTextV20 = engine.BitmapText;
installLegacyPoolAliases(engine, { Slider, Text, BitmapText });
installMelonEditorTextFactories(engine, { Text, BitmapText });
engine.event.on(engine.event.BOOT, () => {
    installMelonEditorTextFactories(engine, { Text, BitmapText });
});

const Particle = ParticleV174;
const ParticleEmitter = ParticleEmitterV174;
const ParticleEmitterSettings = ParticleEmitterSettingsV174;
const ParticleOld = ParticleV174;
const ParticleEmitterOld = ParticleEmitterV174;
const ParticleV20 = engine.Particle;
const ParticleEmitterV20 = engine.ParticleEmitter;
const ParticleEmitterSettingsV20 = engine.ParticleEmitterSettings;
let activeRenderer = engine.game?.renderer;
let activeParticleBridge = null;
const loader = createCompatibleShaderLoader(
    engine,
    () => activeRenderer ?? engine.game?.renderer
);

function createDeferredAdapter(name) {
    let current = null;
    let queuedOptions = [];
    const target = {
        name,
        bind(adapter) {
            current = adapter;
            for (const options of queuedOptions) current.configure?.(options);
            queuedOptions = [];
            return adapter;
        },
        configure(options = {}) {
            if (current) return current.configure?.(options);
            queuedOptions.push(options);
        }
    };

    return new Proxy(target, {
        get(object, property, receiver) {
            if (Reflect.has(object, property)) {
                return Reflect.get(object, property, receiver);
            }
            if (!current) {
                return (...args) => {
                    void args;
                    throw new Error(
                        "Melon Runtime: Application melonJS 20 belum selesai diinisialisasi. " +
                        "Panggil dan await app.init() sebelum memakai API melon.*."
                    );
                };
            }
            const value = current[property];
            return typeof value === "function" ? value.bind(current) : value;
        }
    });
}

const deferredAdapter = createDeferredAdapter("melonjs-20.0.0");

export function createShaderEffect(renderer, source, precision) {
    return createCompatibleShaderEffect(engine, renderer, source, precision);
}

// melonJS 20 does not create a default Application while loading the module.
// Keep a stable Runtime object whose adapter is bound after await app.init().
export let melon = createMelonRuntime(deferredAdapter);

export function configureMelonJs20Runtime(options = {}) {
    const application = options.application ?? engine.game;
    if (!application?.isInitialized || !application.renderer) {
        throw new Error(
            "Melon Runtime: await app.init() sebelum configureMelonJs20Runtime()."
        );
    }
    activeRenderer = application.renderer;
    // Application initialization can register the native pool defaults again.
    installMelonEditorTextFactories(engine, { Text, BitmapText });
    const engineAdapter = createMelonJs20Adapter(engine, { application, audio });
    activeParticleBridge = engineAdapter.particle2D;
    deferredAdapter.bind(engineAdapter);
    if (options.gameData) {
        configureParticleAssets(options.gameData);
        if (!options.gameData.ShaderManager && activeRenderer.gl) {
            options.gameData.ShaderManager = createCompatibleShaderManager(
                engine,
                loader,
                activeRenderer,
                options.gameData.shader
            );
        }
        melon.configure({ gameData: options.gameData });
    } else {
        melon.configure();
    }
    return melon;
}

const ParticleSystem2DRenderableV20 = createMelonJsParticleSystem2DBridge(engine, null, { engineVersion: "20.0.0" }).RenderableClass;
export { ParticleSystem2DRenderableV20 };
export function createAdvancedParticleSystem2DV20(compiledEffect, systemId, emitterId, options = {}) {
    if (!activeParticleBridge) throw new Error("Melon Runtime: configureMelonJs20Runtime() sebelum membuat ParticleSystem2DRenderableV20.");
    return activeParticleBridge.create(compiledEffect, systemId, emitterId, options);
}

export { createMelonRuntime, createMelonJs20Adapter, MELON_RUNTIME_VERSION };
export {
    AudioGroup,
    AudioMixer,
    GUI_Object,
    Slider,
    SliderButton,
    Text,
    BitmapText,
    TextMetrics,
    TextV174,
    BitmapTextV174,
    TextMetricsV174,
    TextV20,
    BitmapTextV20,
    Particle,
    ParticleEmitter,
    ParticleEmitterSettings,
    ParticleOld,
    ParticleEmitterOld,
    ParticleV174,
    ParticleEmitterV174,
    ParticleEmitterSettingsV174,
    ParticleV20,
    ParticleEmitterV20,
    ParticleEmitterSettingsV20,
    audio,
    loader
};
export { melon as default };
