import { evaluateCompiledGradient } from "./particle-values.js";

const clamp01 = value => Math.max(0, Math.min(1, value));
const srgb = value => value <= 0.0031308 ? value * 12.92 : 1.055 * value ** (1 / 2.4) - 0.055;

// Bake once at the engine boundary. Both Canvas and WebGL consume the same image;
// there is no gradient evaluation or canvas allocation inside the particle loop.
export function rasterizeParticleGradient(compiledGradient, settings = {}, size = 128) {
    const width = Math.max(2, Math.min(512, Math.floor(size) || 128));
    const data = new Uint8ClampedArray(width * width * 4);
    const angle = (settings.angle ?? 0) * Math.PI / 180;
    const dx = Math.cos(angle); const dy = Math.sin(angle);
    const span = Math.abs(dx) + Math.abs(dy);
    const color = new Float64Array(4);
    for (let y = 0; y < width; y++) for (let x = 0; x < width; x++) {
        const u = x / (width - 1); const v = y / (width - 1);
        const time = settings.mode === "radial" ? Math.hypot(u - 0.5, v - 0.5) * 2 : 0.5 + ((u - 0.5) * dx + (v - 0.5) * dy) / span;
        evaluateCompiledGradient(compiledGradient, clamp01(time), color);
        const offset = (y * width + x) * 4;
        for (let channel = 0; channel < 3; channel++) data[offset + channel] = Math.round(clamp01(srgb(color[channel])) * 255);
        data[offset + 3] = Math.round(clamp01(color[3]) * 255);
    }
    return { width, height: width, data };
}

export function createParticleGradientTexture(compiledGradient, settings, createCanvas) {
    const pixels = rasterizeParticleGradient(compiledGradient, settings);
    const canvas = createCanvas?.(pixels.width, pixels.height)
        ?? globalThis.document?.createElement?.("canvas")
        ?? (typeof OffscreenCanvas === "function" ? new OffscreenCanvas(pixels.width, pixels.height) : null);
    if (!canvas) throw new Error("Particle gradient textures require a Canvas 2D surface.");
    canvas.width = pixels.width; canvas.height = pixels.height;
    const context = canvas.getContext("2d");
    if (!context) throw new Error("Particle gradient textures require a Canvas 2D context.");
    const image = context.createImageData(pixels.width, pixels.height);
    image.data.set(pixels.data); context.putImageData(image, 0, 0);
    return canvas;
}
