export function createParticlesModule(context) {
    const bridge = () => {
        const value = context.adapter.particle2D;
        if (!value || typeof value.create !== "function") throw Object.assign(new Error("Advanced ParticleSystem2D adapter is unavailable."), { code: "APS_CAP_UNSUPPORTED" });
        return value;
    };
    return Object.freeze({
        create(compiledEffect, systemId, emitterId, options) { return bridge().create(compiledEffect, systemId, emitterId, options); },
        mount(renderable, z) { return bridge().mount(renderable, z); },
        unmount(renderable) { return bridge().unmount(renderable); },
        capabilities() { return bridge().capabilities(); },
        get RenderableClass() { return bridge().RenderableClass; }
    });
}
