function resolveParticleFrame(engine, emitter, gameData) {
    const configuredSource = emitter.settings.image;
    let source = configuredSource;
    let regionName = emitter.settings.region;
    let region;

    if (typeof configuredSource === "string") {
        const textureName = gameData?.imageLocation?.[configuredSource]
            ?? emitter.settings.texture;
        const atlas = gameData?.textureMap?.get?.(textureName);

        if (atlas instanceof engine.TextureAtlas) {
            source = atlas;
            // A TMX Source override is the atlas region name. It must win over
            // the prefab's authored default region.
            regionName = configuredSource;
        } else {
            source = engine.loader?.getImage?.(configuredSource);
        }
    }

    if (!source) {
        throw new Error(
            `${emitter.settings.name ?? "ParticleEmitter"} | ` +
            `particle image/texture '${configuredSource}' not found`
        );
    }

    if (source instanceof engine.TextureAtlas) {
        if (typeof regionName === "string") {
            region = source.getRegion(regionName);
        }

        const image = region ? source.getTexture(region) : source.getTexture();
        return {
            source,
            image,
            offsetX: region?.offset?.x ?? 0,
            offsetY: region?.offset?.y ?? 0,
            width: region?.width ?? image.width,
            height: region?.height ?? image.height
        };
    }

    return {
        source: null,
        image: source,
        offsetX: 0,
        offsetY: 0,
        width: source?.width ?? 1,
        height: source?.height ?? 1
    };
}

function createDefaultParticleTexture(engine, width = 8, height = 8) {
    const target = new engine.CanvasRenderTarget(width, height, {
        offscreenCanvas: true
    });
    target.context.fillStyle = "#fff";
    target.context.fillRect(0, 0, width, height);
    return target;
}

function createParticleEmitterDefaults(engine) {
    return {
        ...engine.ParticleEmitterSettings,
        width: 1,
        height: 1,
        textureSize: 8,
        tint: "#fff",
        totalParticles: 50,
        angle: Math.PI / 2,
        angleVariation: 0,
        minLife: 1000,
        maxLife: 3000,
        lifeTime: 1000,
        speed: 2,
        speedVariation: 1,
        minRotation: 0,
        maxRotation: 0,
        minStartScale: 1,
        maxStartScale: 1,
        startScale: 1,
        minEndScale: 0,
        maxEndScale: 0,
        endScale: 0,
        gravity: 0,
        wind: 0,
        followTrajectory: false,
        textureAdditive: false,
        blendMode: "normal",
        onlyInViewport: true,
        floating: false,
        maxParticles: 10,
        frequency: 100,
        duration: Infinity,
        framesToSkip: 0
    };
}

/**
 * Port the Melon Editor particle behaviour shipped with melonJS 17.4 projects
 * onto newer melonJS releases. The compatibility emitter owns its complete
 * lifecycle so native emitter scheduling and completion rules cannot change
 * the behaviour of generated projects.
 */
export function createMelonJs174ParticleClasses(engine) {
    const availableParticles = [];
    const particleEmitterDefaults = createParticleEmitterDefaults(engine);
    let gameData;

    class ParticleV174 extends engine.Renderable {
        constructor(emitter) {
            const frame = resolveParticleFrame(engine, emitter, gameData);
            super(
                emitter.getRandomPointX(),
                emitter.getRandomPointY(),
                frame.width,
                frame.height
            );
            this.vel = new engine.Vector2d();
            this.frameOffset = new engine.Vector2d();
            this.onResetEvent(emitter, true, frame);
        }

        onResetEvent(emitter, newInstance = false, resolvedFrame) {
            const frame = resolvedFrame ?? resolveParticleFrame(engine, emitter, gameData);

            if (!newInstance) {
                this.pos.set(emitter.getRandomPointX(), emitter.getRandomPointY());
                this.resize(frame.width, frame.height);
                this.currentTransform.identity();
            }

            this.source = frame.source;
            this.image = frame.image;
            this.frameOffset.set(frame.offsetX, frame.offsetY);
            this.resize(frame.width, frame.height);
            this.alwaysUpdate = true;
            this.alive = true;
            this.alpha = 1;

            if (typeof emitter.settings.tint === "string") {
                this.tint.parseCSS(emitter.settings.tint);
            }

            this.blendMode = emitter.settings.textureAdditive ? "additive" : "normal";
            if (emitter.settings.blendMode !== "normal") {
                this.blendMode = emitter.settings.blendMode;
            }

            const angle = emitter.settings.angle + (
                emitter.settings.angleVariation > 0
                    ? (Math.random() * 2 - 1) * emitter.settings.angleVariation
                    : 0
            );
            const speed = emitter.settings.speed + (
                emitter.settings.speedVariation > 0
                    ? (Math.random() * 2 - 1) * emitter.settings.speedVariation
                    : 0
            );

            this.vel.set(speed * Math.cos(angle), -speed * Math.sin(angle));
            this.life = emitter.settings.lifeTime;
            this.startLife = this.life;
            this.startScale = emitter.settings.startScale;
            this.endScale = emitter.settings.endScale;
            this.gravity = emitter.settings.gravity;
            this.wind = emitter.settings.wind;
            this.followTrajectory = emitter.settings.followTrajectory;
            this.onlyInViewport = emitter.settings.onlyInViewport;
            this._deltaInv = engine.timer.maxfps / 1000;

            if (!this.followTrajectory) {
                this.angle = Math.random() * (
                    emitter.settings.maxRotation - emitter.settings.minRotation
                ) + emitter.settings.minRotation;
            }

            const visualAngle = this.followTrajectory
                ? Math.atan2(this.vel.y, this.vel.x)
                : this.angle;
            this.anchorPoint.set(0.5, 0.5);
            this.currentTransform
                .identity()
                .scale(this.startScale, this.startScale)
                .rotate(visualAngle);
            this.updateBounds();
        }

        update(dt) {
            const skew = dt * this._deltaInv;
            this.life = this.life > dt ? this.life - dt : 0;

            if (this.alive && this.life <= 0) {
                const parent = this.ancestor;
                this.alive = false;
                parent?.removeChildNow(this, true);
                availableParticles.push(this);
                return false;
            }

            const ageRatio = this.life / this.startLife;
            let scale = this.startScale;
            const scaleMultiplier = this.startScale +
                (this.endScale - this.startScale) * (1 - ageRatio);
            scale *= scaleMultiplier;

            this.alpha = ageRatio;
            this.vel.x += this.wind * skew;
            this.vel.y += this.gravity * skew;

            const angle = this.followTrajectory
                ? Math.atan2(this.vel.y, this.vel.x)
                : this.angle;
            this.pos.x += this.vel.x * skew;
            this.pos.y += this.vel.y * skew;
            this.currentTransform.identity().scale(scale, scale).rotate(angle);
            this.updateBounds();
            this.isDirty = this.inViewport || !this.onlyInViewport;
            return this.isDirty;
        }

        draw(renderer) {
            renderer.drawImage(
                this.image,
                this.frameOffset.x,
                this.frameOffset.y,
                this.width,
                this.height,
                this.pos.x,
                this.pos.y,
                this.width,
                this.height
            );
        }
    }

    class ParticleEmitterV174 extends engine.Container {
        constructor(x, y, settings = {}) {
            super(x, y, settings.width ?? 1, settings.height ?? 1);

            this.settings = {};
            this.centerOn(x, y);
            this._stream = false;
            this._frequencyTimer = 0;
            this._durationTimer = 0;
            this._enabled = false;
            this._updateCount = 0;
            this._dt = 0;
            this._hasSpawned = false;
            this.spawnInterval = undefined;
            this.spawnTimer = 0;
            this._spawnIntervalTotalParticles = undefined;
            this._spawnIntervalLifeTime = undefined;
            this.alwaysUpdate = true;
            this.autoSort = false;
            this.reset(settings);

            // Melon Editor 17.4 accepted constructor angle overrides in degrees.
            this.settings.angle *= Math.PI / 180;
            this.settings.angleVariation *= Math.PI / 180;
        }

        reset(settings = {}) {
            if (this._destroying) {
                return super.reset();
            }

            if (this._defaultParticle) {
                this._defaultParticle.destroy();
                this._defaultParticle = undefined;
            }

            Object.assign(this.settings, particleEmitterDefaults, settings);
            this.spawnInterval = undefined;
            this.spawnTimer = 0;
            this._spawnIntervalTotalParticles = undefined;
            this._spawnIntervalLifeTime = undefined;
            this._hasSpawned = false;

            if (typeof this.settings.image === "undefined") {
                this._defaultParticle = createDefaultParticleTexture(
                    engine,
                    this.settings.textureSize,
                    this.settings.textureSize
                );
                this.settings.image = this._defaultParticle.canvas;
            }

            this.floating = this.settings.floating;
            this.isDirty = true;
            return this;
        }

        getRandomPointX() {
            return Math.random() * this.getBounds().width;
        }

        getRandomPointY() {
            return Math.random() * this.getBounds().height;
        }

        addParticles(count) {
            const z = this.depth;
            for (let i = 0; i < count; i++) {
                const particle = availableParticles.pop();
                if (particle) particle.onResetEvent(this);
                this.addChild(particle ?? new ParticleV174(this), z);
            }
            if (count > 0) this._hasSpawned = true;
            this.isDirty = true;
        }

        isRunning() {
            return this._enabled && this._stream;
        }

        streamParticles(duration) {
            const wasRunning = this.isRunning();
            this._enabled = true;
            this._stream = true;
            this.settings.frequency = Math.max(1, this.settings.frequency);
            this._durationTimer = typeof duration === "number"
                ? duration
                : this.settings.duration;

            if (!wasRunning) {
                const totalParticles = Math.max(
                    1,
                    Number(this.settings.totalParticles) || 1
                );
                const lifeTime = Math.max(1, Number(this.settings.lifeTime) || 1);
                this.spawnInterval = lifeTime / totalParticles;
                this._spawnIntervalTotalParticles = totalParticles;
                this._spawnIntervalLifeTime = lifeTime;
                this.spawnTimer = 0;
            }
        }

        stopStream() {
            this._enabled = false;
            this.spawnInterval = undefined;
            this._spawnIntervalTotalParticles = undefined;
            this._spawnIntervalLifeTime = undefined;
        }

        burstParticles(total) {
            this._enabled = true;
            this._stream = false;
            this.addParticles(
                typeof total === "number" ? total : this.settings.totalParticles
            );
            this._enabled = false;
        }

        update(dt) {
            const children = this.getChildren();

            // A completed burst remains reusable instead of destroying its emitter.
            if (!this._stream && children.length === 0) {
                return false;
            }

            if (++this._updateCount > this.settings.framesToSkip) {
                this._updateCount = 0;
            }
            if (this._updateCount > 0) {
                this._dt += dt;
                return this.isDirty;
            }

            dt += this._dt;
            this._dt = 0;
            const childrenDirty = super.update(dt);
            this.isDirty = this.isDirty || childrenDirty;

            if (this._enabled && this._stream) {
                if (this._durationTimer !== Infinity) {
                    this._durationTimer -= dt;
                    if (this._durationTimer <= 0) {
                        this.stopStream();
                        return this.isDirty;
                    }
                }

                const totalParticles = Math.max(
                    1,
                    Number(this.settings.totalParticles) || 1
                );
                const lifeTime = Math.max(1, Number(this.settings.lifeTime) || 1);

                if (
                    !this.spawnInterval ||
                    this._spawnIntervalTotalParticles !== totalParticles ||
                    this._spawnIntervalLifeTime !== lifeTime
                ) {
                    this.spawnInterval = lifeTime / totalParticles;
                    this._spawnIntervalTotalParticles = totalParticles;
                    this._spawnIntervalLifeTime = lifeTime;
                    if (!Number.isFinite(this.spawnTimer)) this.spawnTimer = 0;
                }

                this.spawnTimer += dt;
                while (this.spawnTimer >= this.spawnInterval) {
                    this.spawnTimer -= this.spawnInterval;
                    if (this.getChildren().length < totalParticles) {
                        this.addParticles(1);
                        this.isDirty = true;
                    }
                }
            }

            return this.isDirty;
        }

        destroy() {
            const defaultParticle = this._defaultParticle;
            this._defaultParticle = undefined;
            this._destroying = true;
            super.destroy(...arguments);
            this._destroying = false;

            defaultParticle?.destroy();
            if (this.settings) {
                this.settings.image = undefined;
                this.settings = undefined;
            }
        }
    }

    return {
        ParticleV174,
        ParticleEmitterV174,
        ParticleEmitterSettingsV174: particleEmitterDefaults,
        configureParticleAssets(nextGameData) {
            gameData = nextGameData;
        }
    };
}
