import { packParticleColor, unpackParticleColor } from "../particle/particle-state.js";

// Children are owned by their spawning renderable, so pause/restart/unmount and
// preview replacement cannot leave particle effects behind in the game world.
export class ParticleSubEffectChildren {
    constructor(owner, createLocal) { this.owner = owner; this.createLocal = createLocal; this.children = []; }
    spawn(request) {
        const owner = this.owner; const options = owner.instanceOptions;
        const limit = options.subEffectDepthLimit ?? owner.runtime.subEmitters.source.maximumDepth;
        if (request.depth >= limit) return this.fail("APS_SUBEMITTER_DEPTH_LIMIT", "Sub emitter nesting exceeds Maximum depth.");
        const inherited = request.inherited;
        const position = inherited.position ? { ...inherited.position } : { x: owner.pos.x, y: owner.pos.y };
        if (inherited.position && owner.runtime.system.simulationSpace === "local") { position.x += owner.pos.x; position.y += owner.pos.y; }
        const childOptions = {
            application: owner.application, x: position.x, y: position.y, floating: owner.floating,
            prewarm: 0, culling: false, subEffectDepthLimit: limit,
            onSubEffectError: options.onSubEffectError,
            runtimeOptions: { ancestry: request.ancestry, seedOptions: inherited.seed === undefined ? {} : { autoSeed: inherited.seed }, systemOptions: { startDelay: 0, ...(inherited.seed === undefined ? {} : { randomSeed: inherited.seed }), ...(request.followParent ? { simulationSpace: "local" } : {}) } }
        };
        let child;
        try {
            if (request.target.subEffectId) {
                const reference = owner.compiledEffect.asset.dependencies.subEffects.find(item => item.id === request.target.subEffectId);
                if (!reference || !options.createSubEffect) return this.fail("APS_SUBEMITTER_TARGET_MISSING", "Select an available Particle System 2D child object.");
                childOptions.effectKey = String(reference.assetId);
                child = options.createSubEffect(reference, { application: owner.application, particleSystemId: request.target.systemId, particleEmitterId: request.target.emitterId, particleOptions: childOptions });
            } else {
                const asset = owner.compiledEffect.asset;
                const system = request.target.systemId ? owner.compiledEffect.systemById.get(request.target.systemId) : asset.systems.find(item => item.emitters.some(emitter => emitter.id === request.target.emitterId));
                const emitter = request.target.emitterId ? system?.emitters.find(item => item.id === request.target.emitterId) : system?.emitters[0];
                if (!system || !emitter) return this.fail("APS_SUBEMITTER_TARGET_MISSING", "The linked particle emitter no longer exists.");
                child = this.createLocal(owner.compiledEffect, system.id, emitter.id, { ...options, ...childOptions });
            }
            if (!child?.runtime) throw Object.assign(new Error("The selected object is not a Particle System 2D effect."), { code: "APS_SUBEMITTER_TARGET_INVALID" });
            if (!child.sourceEnabled) { child.destroy(); return { spawned: 0 }; }
            child.runtime.system.wantsEmission = false;
            // Inherit values as modifiers, retaining the child shape and authored
            // start properties. Count is an explicit particle burst.
            const scratch = new Float64Array(4);
            const detach = child.runtime.mainEmission.addSpawnInitializer((slot, _id, state) => {
                const start = state.start;
                if (inherited.velocity) { start.velocityX[slot] += inherited.velocity.x; start.velocityY[slot] += inherited.velocity.y; }
                if (inherited.rotation !== undefined) start.rotation[slot] += inherited.rotation;
                if (inherited.size) { start.sizeX[slot] *= inherited.size.x; start.sizeY[slot] *= inherited.size.y; }
                if (inherited.color) { unpackParticleColor(start.color[slot], scratch); for (let i = 0; i < 4; i++) scratch[i] *= inherited.color[i]; start.color[slot] = packParticleColor(...scratch); }
                if (inherited.lifetimeRatio !== undefined) start.lifetime[slot] *= Math.max(0, 1 - inherited.lifetimeRatio);
            });
            let spawned;
            try { spawned = child.runtime.mainEmission.emit(request.count, { customData: inherited.customData?.channels ?? inherited.customData }, false); }
            finally { detach(); }
            if (!spawned) { child.destroy(); return { spawned: 0 }; }
            this.children.push(child);
            const state = child.runtime.system.state; const particleIds = [];
            for (let slot = state.firstActiveSlot(); slot !== -1; slot = state.nextActiveSlot(slot)) particleIds.push(state.particleIdForSlot(slot));
            return {
                spawned, particleIds,
                setTransform: point => {
                    if (child.disposed) return false;
                    child.pos.x = point.x + (owner.runtime.system.simulationSpace === "local" ? owner.pos.x : 0);
                    child.pos.y = point.y + (owner.runtime.system.simulationSpace === "local" ? owner.pos.y : 0);
                    return true;
                },
                // A dying parent releases the follow link; existing child
                // particles finish their own lifetime at the last position.
                dispose() {}
            };
        } catch (error) { child?.destroy?.(); return this.fail(error.code ?? "APS_SUBEMITTER_SPAWN_FAILED", error.message); }
    }
    fail(code, message) {
        if (this.owner.lastSubEffectError?.code === code && this.owner.lastSubEffectError?.message === message) return { spawned: 0 };
        const error = Object.assign(new Error(message), { code });
        this.owner.lastSubEffectError = error;
        if (this.owner.instanceOptions.onSubEffectError) this.owner.instanceOptions.onSubEffectError(error);
        else console.warn(`${code}: ${message}`);
        return { spawned: 0 };
    }
    update(delta) {
        for (let i = this.children.length - 1; i >= 0; i--) {
            const child = this.children[i]; child.update(delta);
            if (child.disposed || (!child.runtime.system.alive && !child.runtime.subEmitters.delayed.length && !child.runtime.trails.detached.length && !child.childEffects.children.length)) { child.destroy(); this.children.splice(i, 1); }
        }
    }
    draw(renderer) { for (const child of this.children) child.draw(renderer); }
    clear() { for (const child of this.children) child.destroy(); this.children.length = 0; }
}
